CHECKS = ["check_classifier", "check_dummy", "check_topk", "check_apply", "check_layer"]


def _t(flat, shape, dtype=torch.float64):
    return torch.tensor(flat, dtype=dtype).reshape(shape)


def _w(f, key_w, key_b, shape):
    return (_t(f[key_w], shape[0:1] + shape[1:2]) if False else _t(f[key_w], shape),
            _t(f[key_b], (shape[0],)))


def check_classifier(solve):
    f = EXPECTED["F1"]
    hs, xs, nl, nc, temp = f["hidden_size"], f["xlora_size"], f["n_layers"], f["n_classes"], f["temp"]
    weights = [
        (_t(f["W1"], (xs, hs)), _t(f["b1"], (xs,))),
        (_t(f["W2"], (xs, xs)), _t(f["b2"], (xs,))),
        (_t(f["W3"], (nc * nl, xs)), _t(f["b3"], (nc * nl,))),
    ]
    hidden = _t(f["hidden"], (2, 5, hs))
    got = solve(mode="classifier_forward", hidden=hidden, weights=weights,
                n_layers=nl, n_classes=nc, temperature=temp)
    want = _t(f["scalings"], (2, 5, nl, nc))
    assert got.shape == (2, 5, nl, nc)
    assert torch.allclose(got, want, atol=1e-10), float((got - want).abs().max())
    # softmax row property
    assert torch.allclose(got.sum(-1), torch.ones(2, 5, nl, dtype=torch.float64), atol=1e-12)
    # temperature observable: different temperature changes scalings
    got_t2 = solve(mode="classifier_forward", hidden=hidden, weights=weights,
                   n_layers=nl, n_classes=nc, temperature=temp * 2)
    assert not torch.allclose(got, got_t2, atol=1e-6)
    # temperature_softmax unit
    logits = torch.tensor([[1.0, 2.0, 3.0]], dtype=torch.float64)
    sm = solve(mode="temperature_softmax", logits=logits, temperature=1.0)
    assert torch.allclose(sm, torch.softmax(logits, dim=-1), atol=1e-12)
    # non-layerwise expand: all layers share the same softmax
    f2 = EXPECTED["F2"]
    weights_n = weights[:2] + [(_t(f2["W3n"], (nc, xs)), _t(f2["b3n"], (nc,)))]
    got_n = solve(mode="classifier_forward", hidden=hidden, weights=weights_n,
                  n_layers=nl, n_classes=nc, temperature=temp, layerwise=False)
    want_n = _t(f2["scalings_nonlayerwise"], (2, 5, nl, nc))
    assert torch.allclose(got_n, want_n, atol=1e-10)
    for L in range(1, nl):
        assert torch.allclose(got_n[:, :, L], got_n[:, :, 0], atol=1e-12)


def check_dummy(solve):
    f = EXPECTED["F1"]
    nl, nc = f["n_layers"], f["n_classes"]
    # default override = 1/n_classes
    d1 = solve(mode="dummy_scalings", batch=2, seq=5, n_layers=nl, n_classes=nc)
    assert torch.allclose(d1, torch.full((2, 5, nl, nc), 1.0 / nc, dtype=torch.float64))
    # explicit override = 0 (official scaling pass default)
    d2 = solve(mode="dummy_scalings", batch=2, seq=5, n_layers=nl, n_classes=nc, override=0.0)
    assert torch.allclose(d2, torch.zeros(2, 5, nl, nc, dtype=torch.float64))
    # explicit value
    d3 = solve(mode="dummy_scalings", batch=1, seq=3, n_layers=2, n_classes=4, override=0.25)
    assert torch.allclose(d3, torch.full((1, 3, 2, 4), 0.25, dtype=torch.float64))


def check_topk(solve):
    f = EXPECTED["F1"]
    nl, nc = f["n_layers"], f["n_classes"]
    scalings = _t(f["scalings"], (2, 5, nl, nc))
    # dense slice: layer_number selects the right slab
    sl0 = solve(mode="maybe_topk_scalings", scalings=scalings, layer_number=0)
    assert torch.allclose(sl0, scalings[:, :, 0], atol=1e-12)
    # topk=1 keeps ORIGINAL values (no renormalization)
    sl_top1 = solve(mode="maybe_topk_scalings", scalings=scalings, layer_number=1, top_k=1)
    am_v, am_i = scalings[:, :, 1].max(-1)
    assert torch.allclose(sl_top1.gather(-1, am_i.unsqueeze(-1)).squeeze(-1), am_v, atol=1e-12)
    onehot = torch.zeros_like(scalings[:, :, 1]).scatter_(-1, am_i.unsqueeze(-1), 1.0)
    assert torch.allclose(sl_top1, scalings[:, :, 1] * onehot, atol=1e-12)
    assert not torch.allclose(sl_top1.sum(-1), torch.ones(2, 5, dtype=torch.float64), atol=1e-3)
    # softmax_topk renormalizes over nonzero slots; zeros stay zero
    sl_st = solve(mode="maybe_topk_scalings", scalings=scalings, layer_number=1, top_k=2,
                  enable_softmax_topk=True)
    assert torch.allclose(sl_st.sum(-1), torch.ones(2, 5, dtype=torch.float64), atol=1e-12)
    nz = sl_st != 0
    full = scalings[:, :, 1].masked_fill(~nz, float("-inf"))
    manual = torch.softmax(full, dim=-1).masked_fill(~nz, 0.0)
    assert torch.allclose(sl_st, manual, atol=1e-12)
    # topk=1 + softmax_topk == one-hot
    sl_1h = solve(mode="maybe_topk_scalings", scalings=scalings, layer_number=2, top_k=1,
                  enable_softmax_topk=True)
    assert torch.allclose(sl_1h.max(-1).values, torch.ones(2, 5, dtype=torch.float64), atol=1e-12)
    # dense with softmax_topk (top_k=None): plain softmax (all slots nonzero)
    sl_full = solve(mode="maybe_topk_scalings", scalings=scalings, layer_number=0,
                    enable_softmax_topk=True)
    assert torch.allclose(sl_full, torch.softmax(scalings[:, :, 0], dim=-1), atol=1e-12)
    # top_k = n_classes: topk keeps ALL experts -> identical to dense slice
    sl_all = solve(mode="maybe_topk_scalings", scalings=scalings, layer_number=1, top_k=nc)
    assert torch.allclose(sl_all, scalings[:, :, 1], atol=1e-12)
    # all-zero row: softmax_topk must produce zeros, not NaN (softmax of all -inf)
    scalings_z = scalings.clone()
    scalings_z[:, 2, 1, :] = 0.0  # batch 0/1, token 2, layer 1: all experts zero
    sl_z = solve(mode="maybe_topk_scalings", scalings=scalings_z, layer_number=1, top_k=1,
                 enable_softmax_topk=True)
    assert torch.allclose(sl_z[:, 2], torch.zeros(2, nc, dtype=torch.float64), atol=1e-12), sl_z[:, 2]
    assert torch.isfinite(sl_z).all()


def check_apply(solve):
    f = EXPECTED["F1"]
    nl, nc = f["n_layers"], f["n_classes"]
    scalings = _t(f["scalings"], (2, 5, nl, nc))
    sl = scalings[:, :, 0, :]
    hidden = _t(f["hidden"], (2, 5, f["hidden_size"]))
    # input-side scaling: x * lambda per adapter
    got = solve(mode="apply_scalings_to_x", x=hidden, scalings_layer=sl, adapter=0)
    assert torch.allclose(got, hidden * sl[:, :, 0].unsqueeze(-1), atol=1e-12)
    got1 = solve(mode="apply_scalings_to_x", x=hidden, scalings_layer=sl, adapter=1)
    assert torch.allclose(got1, hidden * sl[:, :, 1].unsqueeze(-1), atol=1e-12)
    assert not torch.allclose(got, got1, atol=1e-9)
    # einsum equivalence: (x * lam) @ M.T == einsum("bsi,bs,oi->bso")
    lam = sl[:, :, 0]
    m = torch.randn(6, f["hidden_size"], dtype=torch.float64)
    xmod = hidden * lam.unsqueeze(-1)
    manual = torch.einsum("bsi,bs,oi->bso", hidden, lam, m)
    assert torch.allclose(xmod @ m.T, manual, atol=1e-12)


def check_layer(solve):
    f = EXPECTED["F1"]
    nl, nc = f["n_layers"], f["n_classes"]
    f3 = EXPECTED["F3"]
    scalings = _t(f["scalings"], (2, 5, nl, nc))
    hidden = _t(f["hidden"], (2, 5, f["hidden_size"]))
    r = f3["r"]
    lora_pairs = [(_t(f3["A"][a], (r, f3["in_d"])), _t(f3["B"][a], (f3["out_d"], r)))
                  for a in range(nc)]
    base_weight = _t(f3["W0"], (f3["out_d"], f3["in_d"]))
    got = solve(mode="layer_forward", x=hidden, scalings=scalings, lora_pairs=lora_pairs,
                scaling=f3["scaling"], global_scaling_weight=f3["gw"], layer_number=0,
                base_weight=base_weight)
    want = _t(f3["layer0_out"], (2, 5, f3["out_d"]))
    assert torch.allclose(got, want, atol=1e-10), float((got - want).abs().max())
    # manual dense path
    sl0 = scalings[:, :, 0, :]
    delta = sum(
        (hidden * sl0[:, :, a].unsqueeze(-1)) @ lora_pairs[a][0].T @ lora_pairs[a][1].T
        * f3["scaling"] * f3["gw"] for a in range(nc))
    assert torch.allclose(got, hidden @ base_weight.T + delta, atol=1e-10)
    # scalings=None: plain LoRA sum, no global weight
    plain = solve(mode="layer_forward", x=hidden, scalings=None, lora_pairs=lora_pairs,
                  scaling=f3["scaling"], global_scaling_weight=f3["gw"], layer_number=0,
                  base_weight=base_weight)
    delta_plain = sum(hidden @ lora_pairs[a][0].T @ lora_pairs[a][1].T * f3["scaling"]
                      for a in range(nc))
    assert torch.allclose(plain, hidden @ base_weight.T + delta_plain, atol=1e-10)
    assert not torch.allclose(plain, got, atol=1e-9)
    # topk path observable
    got_tk = solve(mode="layer_forward", x=hidden, scalings=scalings, lora_pairs=lora_pairs,
                   scaling=f3["scaling"], global_scaling_weight=f3["gw"], layer_number=1,
                   base_weight=base_weight, top_k=1)
    assert not torch.allclose(got_tk, got, atol=1e-9)
    # global_scaling_weight observable
    got_gw = solve(mode="layer_forward", x=hidden, scalings=scalings, lora_pairs=lora_pairs,
                   scaling=f3["scaling"], global_scaling_weight=f3["gw"] * 2, layer_number=0,
                   base_weight=base_weight)
    assert not torch.allclose(got_gw, got, atol=1e-9)
    # gw multiplies only the lora paths: got_gw = base + 2 * (got - base)
    assert torch.allclose(got_gw, hidden @ base_weight.T + 2 * (got - hidden @ base_weight.T),
                          atol=1e-10)


def solve(mode=None, **kw):
    import solution
    return solution.solve(mode=mode, **kw)
